// @vitest-environment node
// Drift guard: every endpoint the web client calls must exist, with that method, in the services' exported OpenAPI specs
// (engine/openapi.json and agent/openapi.json, regenerated by `npm run gen:api` after a backend change).
import { readFileSync } from "node:fs";
import { describe, expect, it } from "vitest";

type Spec = { paths: Record<string, Record<string, unknown>> };
const load = (name: string): Spec => JSON.parse(readFileSync(new URL(`../../../${name}/openapi.json`, import.meta.url), "utf-8"));
const engine = load("engine");
const agent = load("agent");

const ENGINE_CALLS: [string, string][] = [
  ["get", "/health"], ["get", "/cities"], ["get", "/eval/results"], ["get", "/tickets"], ["get", "/tickets/{ticket_id}"], ["get", "/tickets/{ticket_id}/score"],
  ["get", "/wards/stats"], ["get", "/wards/map"], ["post", "/satellite/check"], ["get", "/satellite/chip/{ticket_id}/{which}.png"], ["get", "/media/demo/{ticket_id}/{which}.jpg"],
];
const AGENT_CALLS: [string, string][] = [
  ["get", "/health"], ["get", "/auth/me"], ["post", "/auth/profile"], ["get", "/me/tickets"],
  ["get", "/admin/users"], ["post", "/admin/users/{user_id}/approve"], ["post", "/admin/users/{user_id}/reject"], ["post", "/admin/users/{user_id}/role"],
  ["post", "/admin/users/{user_id}/tickets"], ["delete", "/admin/users/{user_id}/tickets/{ticket_id}"],
  ["get", "/verification/{ticket_id}/latest"], ["post", "/agent/run/{ticket_id}"], ["get", "/agent/stream/{run_id}"],
  ["get", "/approvals"], ["post", "/approvals/{approval_id}/decide"], ["get", "/audit"], ["get", "/audit/verify"],
  ["post", "/citizen/reply-links"], ["get", "/reply/{token}"], ["post", "/reply/{token}"],
];

describe("web client against the exported OpenAPI specs", () => {
  it.each(ENGINE_CALLS)("Engine %s %s exists", (method, path) => {
    expect(Object.keys(engine.paths[path] ?? {})).toContain(method);
  });
  it.each(AGENT_CALLS)("Agent %s %s exists", (method, path) => {
    expect(Object.keys(agent.paths[path] ?? {})).toContain(method);
  });
});
